var a=[{title:`Moduri de a număra munca`,text:`Cea mai simplă numărătoare este numărul de serii de lucru. „Volumul de sarcină” înmulțește serii × repetări × greutate, deci trei serii de zece cu 40 kg dau 1.200 kg de volum de sarcină pentru acel exercițiu. Asta ajută când compari aceeași mișcare în timp. Nu funcționează între exerciții: o împingere la aparat și o flotare cu greutatea corpului nu se traduc în aceleași kilograme de stimul.`},{title:`Serii grele pe mușchi`,text:`Pentru creșterea musculară, antrenorii numără adesea seriile grele care încarcă fiecare grupă musculară. Ridicările compuse contează pentru mai mulți mușchi, deși nu întotdeauna în mod egal. O genuflexiune antrenează puternic extensorii genunchiului și ai șoldului, în timp ce ramatul adaugă lucru pentru spate și brațe. Dacă numeri fiecare mușchi implicat ca și cum ar fi primit același stimul, totalurile tale vor ieși prea mari.`},{title:`Câte serii să faci`,text:`Declarația de poziție ACSM 2026 a constatat că volumele săptămânale mai mari, inclusiv cel puțin aproximativ zece serii pe grupă musculară, pot crește hipertrofia. Aceasta nu este o doză de început pentru toată lumea și nu garantează progresul. Începătorii se îmbunătățesc adesea cu mai puține serii. Cei mai experimentați pot beneficia de mai multe, dacă timpul, tehnica și refacerea o permit.`},{title:`Construiește treptat`,text:`Un începător poate începe cu două serii din mai multe tipare pe sesiune, de două ori pe săptămână. După câteva săptămâni de performanță constantă, adaugă o serie la un tipar rămas în urmă doar dacă febra musculară, somnul și calitatea sesiunii o permit. Un salt de la șase la douăzeci de serii grele pe săptămână pentru un mușchi adaugă risc de oboseală fără un motiv bun.`},{title:`Calitate și cantitate`,text:`Seriile făcute cu tehnică slabă, cu puțin efort sau cu oboseală mare ridică totuși totalul dintr-un tabel, dar adaugă puțin. Progresul constant, susținut, contează mai mult decât cel mai mare volum.`},{title:`Folosind TrainUp`,text:`În fiecare antrenament îți bifezi seriile și îți notezi repetările, iar Istoricul arată efortul tău mediu și un grafic pe 4 săptămâni. Compară săptămâni asemănătoare. Dacă efortul este mai mare decât te așteptai sau repetările scad, uită-te la volum înainte să adaugi mai mult.`}];var t=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Analiză a mecanismelor hipertrofiei`,url:`https://pubmed.ncbi.nlm.nih.gov/35389932/`}];var r={sections:a,sources:t};export{r as default,a as sections,t as sources};